374	export async function assetUrl(path: string | null) {
375	  if (!path) return undefined;
376	  if (isElectronRuntime()) {
377	    const relativePath = path.replace(/\\/g, "/");
378	    if (!relativePath.startsWith("assets/")) return undefined;
379	    const segments = relativePath.slice("assets/".length).split("/");
380	    if (
381	      segments.some(
382	        (segment) => !segment || segment === "." || segment === ".." || segment.includes(":"),
383	      )
384	    ) {
385	      return undefined;
386	    }
387	    const encodedPath = segments.map(encodeURIComponent).join("/");
388	    return `app://local/library-assets/${encodedPath}`;
389	  }
390	  return path;
391	}
