8	export function validateImageDimensions(width, height) {
9	  if (!width || !height) throw new Error("image processing error: unable to decode image");
10	  if (
11	    width > maxImageDimension ||
12	    height > maxImageDimension ||
13	    width * height * 8 > maxImageAllocation
14	  ) {
