56	export async function sharpImageInput(bytes) {
57	  try {
58	    await sharp(bytes, { limitInputPixels: maxImagePixels }).metadata();
59	    return bytes;
60	  } catch (error) {
61	    const isBitmap = bytes.subarray(0, 2).toString("ascii") === "BM";
62	    const isIcon = bytes.length >= 6 && bytes.readUInt16LE(0) === 0 && bytes.readUInt16LE(2) === 1;
63	    if (!isBitmap && !isIcon) throw error;
64	    if (isIcon) validateIconImage(bytes);
65	    if (isBitmap && bytes.length >= 26) {
66	      const coreHeader = bytes.readUInt32LE(14) === 12;
67	      const width = coreHeader ? bytes.readUInt16LE(18) : bytes.readInt32LE(18);
68	      const height = coreHeader ? bytes.readUInt16LE(20) : bytes.readInt32LE(22);
69	      validateImageDimensions(Math.abs(width), Math.abs(height));
70	    }
71	    const [{ CanvasElement }, { default: loadImage }] = await Promise.all([
72	      import("@napi-rs/canvas/js-binding.js"),
73	      import("@napi-rs/canvas/load-image.js"),
74	    ]);
75	    const image = await loadImage(bytes);
76	    validateImageDimensions(image.width, image.height);
77	    const canvas = new CanvasElement(image.width, image.height);
78	    canvas.getContext("2d").drawImage(image, 0, 0);
79	    return canvas.encode("png");
80	  }
81	}
