83	export async function createImageThumbnail(bytes) {
84	  const input = await sharpImageInput(bytes);
85	  const image = sharp(input, { limitInputPixels: maxImagePixels });
86	  const { width, height, orientation } = await image.metadata();
87	  validateImageDimensions(width, height);
88	  const isRotated = orientation != null && orientation >= 5 && orientation <= 8;
89	  const thumbnail = await image
90	    .rotate()
91	    .resize({
92	      width: thumbnailEdge,
93	      height: thumbnailEdge,
94	      fit: "inside",
95	      withoutEnlargement: true,
96	    })
97	    .webp()
98	    .toBuffer();
99	  return {
100	    bytes: thumbnail,
101	    width: isRotated ? height : width,
102	    height: isRotated ? width : height,
103	  };
104	}
