106	export async function dominantImageColors(bytes) {
107	  const input = await sharpImageInput(bytes);
108	  const { data, info } = await sharp(input, { limitInputPixels: maxImagePixels })
109	    .resize({ width: 64, height: 64, fit: "inside", withoutEnlargement: true })
110	    .removeAlpha()
111	    .raw()
112	    .toBuffer({ resolveWithObject: true });
113	  const bins = new Map();
114	  for (let index = 0; index < data.length; index += info.channels) {
115	    const red = data[index] >> 4;
116	    const green = data[index + 1] >> 4;
117	    const blue = data[index + 2] >> 4;
118	    const key = (red << 8) | (green << 4) | blue;
119	    bins.set(key, (bins.get(key) ?? 0) + 1);
120	  }
121	  const colors = [...bins]
122	    .sort((left, right) => right[1] - left[1])
123	    .slice(0, 5)
124	    .map(
125	      ([key]) =>
126	        `#${((key >> 8) * 17).toString(16).padStart(2, "0")}${(((key >> 4) & 15) * 17).toString(16).padStart(2, "0")}${((key & 15) * 17).toString(16).padStart(2, "0")}`,
127	    );
128	  while (colors.length < 5) colors.push(colors.at(-1) ?? "#000000");
129	  return colors;
130	}
