1	import { readFile } from "node:fs/promises";
2	import { join } from "node:path";
3	import { createEmbeddingEngine } from "./embeddings.mjs";
4	import { IMAGE_MODEL } from "./embedding-contract.mjs";
5	import { createTesseractOcr } from "./ocr.mjs";
6	import {
7	  IMAGE_PALETTE_JOB,
8	  markdownToPlainText,
9	  PDF_THUMBNAIL_JOB,
10	  VIDEO_POSTER_JOB,
11	} from "./storage.mjs";
12	
13	async function itemAsset(storage, item) {
14	  if (!item?.localAssetPath) throw new Error("item has no local asset path");
15	  return readFile(await storage.resolveAssetPath(item.localAssetPath));
16	}
17	
18	export function embeddingText(item) {
19	  const bodyValue = String(item.body ?? "").trim();
20	  const body = bodyValue
21	    ? item.bodyFormat === "md"
22	      ? markdownToPlainText(bodyValue)
23	      : bodyValue
24	    : null;
25	  const description = body ?? item.description;
26	  const parts = [item.title, description, item.ocrText]
27	    .map((value) => String(value ?? "").trim())
28	    .filter(Boolean);
29	
30	  if (body == null) {
31	    for (const key of ["text", "extractedText"]) {
32	      const value = String(item.metadata?.[key] ?? "").trim();
33	      if (value) parts.push(value);
34	    }
35	  }
36	
37	  return parts.length ? parts.join("\n\n") : null;
38	}
39	
40	export function enqueueStaleImageEmbeddings(storage) {
41	  const items = storage.db
42	    .prepare(`SELECT e.item_id FROM item_embeddings e JOIN items i ON i.id = e.item_id
43	      WHERE e.kind = 'image' AND e.model != ? AND i.kind = 'image'`)
44	    .all(IMAGE_MODEL);
45	  for (const item of items)
46	    storage.jobs.enqueue(item.item_id, "generate_embedding", { notify: false });
47	  return items.length;
48	}
49	
50	export function createAiJobProcessors({
51	  modelCacheDirectory,
52	  bundledModelDirectory,
53	  ocr = createTesseractOcr({ cacheDirectory: join(modelCacheDirectory, "tesseract") }),
54	  embeddings = createEmbeddingEngine(modelCacheDirectory, undefined, bundledModelDirectory),
55	  extractPdf,
56	  extractUrl = async (sourceUrl) => {
57	    const { ingestUrl } = await import("../dist/electron/url-ingestion.mjs");
58	    return ingestUrl(sourceUrl);
59	  },
60	  nativeImage,
61	} = {}) {
62	  let thumbnailCursor = 0;
63	  let thumbnailBackfillDone = false;
64	  let paletteCursor = 0;
65	  let paletteBackfillDone = false;
66	  let posterCursor = 0;
67	  let posterBackfillDone = false;
68	
69	  const processors = {
70	    async enrich_url(job, storage, workerId) {
71	      const item = storage.getItem(job.itemId);
72	      if (!item) throw new Error("item not found");
73	      if (!item.sourceUrl) throw new Error("URL item has no source URL");
74	      const article = await extractUrl(item.sourceUrl);
75	      storage.applyUrlEnrichment(job.id, workerId, article);
76	    },
77	
78	    async ocr_image(job, storage, workerId) {
79	      const item = storage.getItem(job.itemId);
80	      if (!item) throw new Error("item not found");
81	      storage.jobs.updateProgress(job.id, workerId, 0, 1, "Reading image");
82	      const text = (await ocr.recognize(await itemAsset(storage, item))).trim();
83	      if (text) {
84	        storage.storeOcrText(item.id, text, "tesseract.js");
85	        storage.jobs.enqueue(item.id, "generate_embedding");
86	        storage.jobs.updateProgress(job.id, workerId, 1, 1, "Image text indexed");
87	      } else {
88	        storage.jobs.updateProgress(job.id, workerId, 1, 1, "No text found");
89	      }
90	    },
91	
92	    async ocr_pdf_page(job, storage, workerId) {
93	      const item = storage.getItem(job.itemId);
94	      if (!item) throw new Error("item not found");
95	      let result;
96	      try {
97	        const pdfBytes = await itemAsset(storage, item);
98	        const extract = extractPdf ?? (await import("./pdf.mjs")).extractPdfTextByPages;
99	        result = await extract(pdfBytes, {
100	          recognize: (image) => ocr.recognize(image),
101	          onFirstPageThumbnail: item.thumbnailPath
102	            ? undefined
103	            : (png) => storage.storePdfThumbnail(item.id, png),
104	          onProgress: (current, total, message) =>
105	            storage.jobs.updateProgress(job.id, workerId, current, total, message),
106	        });
107	      } finally {
108	        if (!storage.getItem(item.id)?.thumbnailPath) {
109	          thumbnailCursor = 0;
110	          thumbnailBackfillDone = false;
111	        }
112	      }
113	      const pageCount = result.pages.length;
114	      if (result.text) {
115	        storage.storeOcrText(item.id, result.text, result.engine);
116	        storage.jobs.enqueue(item.id, "generate_embedding");
117	        storage.jobs.updateProgress(job.id, workerId, pageCount, pageCount, "PDF text indexed");
118	      } else {
119	        storage.jobs.updateProgress(job.id, workerId, pageCount, pageCount, "No text found");
120	      }
121	    },
122	
123	    async [PDF_THUMBNAIL_JOB](job, storage) {
124	      const item = storage.getItem(job.itemId);
125	      if (!item) throw new Error("item not found");
126	      const pdfBytes = await itemAsset(storage, item);
127	      const { renderPdfFirstPage } = await import("./pdf.mjs");
128	      await storage.storePdfThumbnail(item.id, await renderPdfFirstPage(pdfBytes));
129	    },
130	
131	    async [VIDEO_POSTER_JOB](job, storage) {
132	      const item = storage.getItem(job.itemId);
133	      if (item?.kind !== "video") throw new Error("video item not found");
134	      if (!item.localAssetPath) throw new Error("item has no local asset path");
135	      const { createVideoPoster } = await import("./video-poster.mjs");
136	      const poster = await createVideoPoster(await storage.resolveAssetPath(item.localAssetPath), {
137	        nativeImage,
138	      });
139	      if (!poster) throw new Error("no poster available for this video");
140	      await storage.storeVideoPoster(item.id, poster);
141	    },
142	
143	    async [IMAGE_PALETTE_JOB](job, storage) {
144	      const item = storage.getItem(job.itemId);
145	      if (item?.kind !== "image") throw new Error("image item not found");
146	      if (!item.thumbnailPath) throw new Error("image thumbnail is not ready");
147	      const { dominantImageColors } = await import("./thumbnail.mjs");
148	      const colors = await dominantImageColors(
149	        await readFile(await storage.resolveAssetPath(item.thumbnailPath)),
150	      );
151	      storage.storeImagePalette(item.id, colors);
152	    },
153	
154	    async generate_embedding(job, storage, workerId) {
155	      const item = storage.getItem(job.itemId);
156	      if (!item) throw new Error("item not found");
157	      const text = embeddingText(item);
158	      const total = Number(Boolean(text)) + Number(item.kind === "image");
159	      storage.jobs.updateProgress(
160	        job.id,
161	        workerId,
162	        0,
163	        total,
164	        "Loading local Nomic embedding models",
165	      );
166	      let current = 0;
167	
168	      if (text) {
169	        const embedding = await embeddings.embedText(text);
170	        storage.storeEmbedding(
171	          item.id,
172	          "text",
173	          embedding.model,
174	          embedding.bytes,
175	          embedding.vector.length,
176	        );
177	        current += 1;
178	        storage.jobs.updateProgress(job.id, workerId, current, total, "Text search index ready");
179	      }
180	
181	      if (item.kind === "image") {
182	        const embedding = await embeddings.embedImage(await itemAsset(storage, item));
183	        storage.storeEmbedding(
184	          item.id,
185	          "image",
186	          embedding.model,
187	          embedding.bytes,
188	          embedding.vector.length,
189	        );
190	        storage.jobs.updateProgress(
